package cn.xingbao.controller;
import cn.xingbao.common.ApiResponse; import cn.xingbao.domain.DirectMessage; import cn.xingbao.repo.MessageRepository; import cn.xingbao.service.RiskService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/messages") public class MessageController { private final MessageRepository messages; private final RiskService risk; public MessageController(MessageRepository m,RiskService r){messages=m;risk=r;} @GetMapping public ApiResponse<List<DirectMessage>> list(@RequestParam Long userId){return ApiResponse.ok(messages.findByFromUserIdOrToUserIdOrderByCreatedAtDesc(userId,userId));} @PostMapping public ApiResponse<DirectMessage> send(@RequestBody DirectMessage m){if("HIGH".equals(risk.evaluate(m.getBody())))throw new IllegalArgumentException("消息包含平台禁止内容，请修改后发送");return ApiResponse.ok(messages.save(m));} }
